#!/usr/bin/env node
/**
 * Ensure index.mdx pages in autogenerated sidebar directories have
 * sidebar.order: 0 so they appear first in their sidebar group.
 *
 * Run as: node apps/dox/scripts/ensure-sidebar-order.mjs
 *
 * Wired to the `generate` Nx target, which `build`, `dev`, and `typecheck`
 * all depend on.
 */

import { existsSync, readdirSync, readFileSync, statSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const appRoot = resolve(__dirname, "..");
const contentDir = resolve(appRoot, "src", "content", "docs");

function findIndexMdx(dir, results = []) {
  if (!existsSync(dir)) return results;
  for (const entry of readdirSync(dir)) {
    const full = join(dir, entry);
    const stat = statSync(full);
    if (stat.isDirectory()) {
      findIndexMdx(full, results);
    } else if (entry === "index.mdx") {
      results.push(full);
    }
  }
  return results;
}

const indexFiles = findIndexMdx(contentDir).filter(
  (f) => f !== join(contentDir, "index.mdx"),
);

let changed = 0;
for (const file of indexFiles) {
  const original = readFileSync(file, "utf-8");
  const content = ensureOrder0(original);
  if (content !== original) {
    writeFileSync(file, content);
    changed++;
  }
}

console.log(`[sidebar-order] ensured order: 0 on ${changed} index page(s)`);

function ensureOrder0(markdown) {
  const fmEnd = markdown.indexOf("\n---", 3);
  if (fmEnd === -1) return markdown;

  const fm = markdown.slice(3, fmEnd);
  const afterFm = markdown.slice(fmEnd + 4);

  const sidebarOrderMatch = fm.match(/^sidebar:\n\s*order:\s*(\d+)/m);
  if (sidebarOrderMatch && Number(sidebarOrderMatch[1]) === 0) {
    return markdown;
  }

  let newFm;
  if (sidebarOrderMatch) {
    newFm = fm.replace(/^sidebar:\n\s*order:\s*\d+/m, "sidebar:\n  order: 0");
  } else if (fm.includes("sidebar:")) {
    newFm = fm.replace(/^sidebar:\n/m, "sidebar:\n  order: 0\n");
  } else {
    newFm = fm + "\nsidebar:\n  order: 0";
  }

  return "---\n" + newFm + "\n---\n" + afterFm;
}
